"""samay's tithi/nakshatra/karana/yoga boundaries vs Swiss Ephemeris (Moshier), generated by
scripts/golden_panchang.py. A failure is a finding to investigate, not a tolerance to loosen."""

import json
from datetime import datetime, timedelta
from pathlib import Path

import pytest

from samay.engine import panchang
from samay.engine.paths import EPHEMERIS_PATH

pytestmark = pytest.mark.skipif(
    not EPHEMERIS_PATH.exists(), reason="ephemeris file not present"
)

CASES = json.loads(
    (Path(__file__).parent / "fixtures" / "golden_panchang.json").read_text()
)["cases"]
# The Moon moves about 30 arcseconds a minute; DE440 and Moshier agree far inside that.
TOLERANCE = timedelta(minutes=1)
# Known, measured difference (found 2026-11-21): samay's sidereal longitudes are apparent (true equinox, so they include
# nutation, about 18 arcseconds) minus a MEAN ayanamsa; Swiss Ephemeris sidereal positions carry no nutation. The offset
# cancels in a tithi or karana (Moon minus Sun), shows once in a nakshatra (about 30 s) and twice in a yoga (Sun plus
# Moon, about 1 minute). No v1 observance uses yoga. Whether to subtract a true ayanamsa instead is an owner decision
# (HANDOFF.md section 5, "mean Lahiri vs true Chitrapaksha") because it moves every chart; until then yoga is checked
# against a 2-minute tolerance and the others against one minute.
TOLERANCES = {
    "tithi": TOLERANCE,
    "karana": TOLERANCE,
    "nakshatra": TOLERANCE,
    "yoga": timedelta(minutes=2),
}


@pytest.mark.parametrize("case", CASES, ids=[c["instant"] for c in CASES])
@pytest.mark.parametrize("kind", ["tithi", "nakshatra", "karana", "yoga"])
def test_boundaries_match_swiss_ephemeris_within_a_minute(case, kind):
    theirs = case[kind]
    ours = panchang.element_at(kind, datetime.fromisoformat(case["instant"]))
    assert ours.number == theirs["number"]
    assert abs(ours.start - datetime.fromisoformat(theirs["start"])) <= TOLERANCES[kind]
    assert abs(ours.end - datetime.fromisoformat(theirs["end"])) <= TOLERANCES[kind]
